// Generates TypeScript types from the OpenAPI documents of the running services (frontend.md, Q9).
// Run the services first (Rider or `docker compose -f compose.dev.yaml --profile services up -d`), then `npm run api:types`.
// The generated files are committed, so building the app never needs the services.
import { writeFile } from 'node:fs/promises'
import openapiTS, { astToString } from 'openapi-typescript'

const services = {
  auth: process.env.AUTH_OPENAPI ?? 'http://localhost:5100/openapi/v1.json',
  accounts: process.env.ACCOUNTS_OPENAPI ?? 'http://localhost:5200/openapi/v1.json',
  households: process.env.HOUSEHOLDS_OPENAPI ?? 'http://localhost:5300/openapi/v1.json',
}

for (const [name, url] of Object.entries(services)) {
  const ast = await openapiTS(new URL(url))
  const header = `// Generated by \`npm run api:types\` from ${url}. Do not edit.\n\n`
  await writeFile(new URL(`../src/api/types/${name}.ts`, import.meta.url), header + astToString(ast))
  console.log(`${name}: ${url}`)
}
